-- setup.sql — sample database for: Exercise 6 — synchronise a price list with MERGE, safely
-- Drops and re-creates the database DBI202_CL (a scratch database used only by Code Lab exercises), then the tables + rows.
-- Xoá và tạo lại CSDL DBI202_CL (CSDL nháp chỉ dùng cho bài Code Lab), rồi tạo bảng + dữ liệu. Chạy lại bất cứ lúc nào để làm sạch.
USE master;
GO
IF DB_ID(N'DBI202_CL') IS NOT NULL
BEGIN
    ALTER DATABASE DBI202_CL SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE DBI202_CL;
END
GO
CREATE DATABASE DBI202_CL;
GO
USE DBI202_CL;
GO
CREATE TABLE dbo.BangGia (
    maHang      VARCHAR(10)   NOT NULL CONSTRAINT pk_banggia PRIMARY KEY,
    tenHang     NVARCHAR(50)  NOT NULL,
    gia         DECIMAL(12,0) NOT NULL,
    ngayCapNhat DATE          NOT NULL
);
CREATE TABLE dbo.GiaMoi (
    maHang  VARCHAR(10)   NOT NULL PRIMARY KEY,
    tenHang NVARCHAR(50)  NOT NULL,
    gia     DECIMAL(12,0) NOT NULL
);
INSERT INTO dbo.BangGia VALUES ('BUT', N'Bút bi', 5000, '2026-01-01'), ('VO', N'Vở', 12000, '2026-01-01'),
                               ('THUOC', N'Thước', 8000, '2026-01-01'), ('TAY', N'Tẩy', 3000, '2026-01-01');
INSERT INTO dbo.GiaMoi VALUES ('BUT', N'Bút bi', 5000), ('VO', N'Vở', 13000), ('THUOC', N'Thước', 7500), ('KEO', N'Keo dán', 6000);
GO
PRINT N'setup.sql: database DBI202_CL ready.';

-- check.sql — self-check for: Exercise 6 — synchronise a price list with MERGE, safely
-- Generated with the exercise — DO NOT EDIT. Run it AFTER setup.sql and your solution.sql (see the task text).
-- Tự kiểm cho bài này — sinh kèm đề, ĐỪNG SỬA. Chạy SAU setup.sql và solution.sql của bạn (xem đề).
USE DBI202_CL;
GO
SET NOCOUNT ON;
DECLARE @ok BIT, @info NVARCHAR(4000), @pass INT = 0, @fail INT = 0;
PRINT N'────────── check.sql: 4 checks ──────────';

-- CHECK 1: The report: VO and THUOC updated, KEO inserted — nothing else
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (hanhDong NVARCHAR(10), maHang VARCHAR(10), gia DECIMAL(12,0));
INSERT INTO @r EXEC dbo.prDongBoGia;
SET @ok = IIF((SELECT COUNT(*) FROM @r) = 3 AND EXISTS (SELECT 1 FROM @r WHERE hanhDong = N''UPDATE'' AND maHang = ''VO'' AND gia = 13000) AND EXISTS (SELECT 1 FROM @r WHERE hanhDong = N''UPDATE'' AND maHang = ''THUOC'' AND gia = 7500) AND EXISTS (SELECT 1 FROM @r WHERE hanhDong = N''INSERT'' AND maHang = ''KEO'' AND gia = 6000), 1, 0);
SET @info = CONCAT(N''report rows: '', (SELECT STRING_AGG(CONCAT(hanhDong, '' '', maHang), '', '') FROM @r));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 1. The report: VO and THUOC updated, KEO inserted — nothing else | Báo cáo: VO và THUOC cập nhật, KEO thêm mới — không gì khác'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 1. The report: VO and THUOC updated, KEO inserted — nothing else | Báo cáo: VO và THUOC cập nhật, KEO thêm mới — không gì khác', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 2: The price list now: BUT unchanged (old date), VO 13000, THUOC 7500, TAY kept, KEO added
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'SET @ok = IIF((SELECT COUNT(*) FROM dbo.BangGia) = 5 AND EXISTS (SELECT 1 FROM dbo.BangGia WHERE maHang = ''BUT'' AND gia = 5000 AND ngayCapNhat = ''2026-01-01'') AND EXISTS (SELECT 1 FROM dbo.BangGia WHERE maHang = ''TAY'' AND gia = 3000)
  AND EXISTS (SELECT 1 FROM dbo.BangGia WHERE maHang = ''VO'' AND gia = 13000 AND ngayCapNhat = CAST(GETDATE() AS DATE)) AND EXISTS (SELECT 1 FROM dbo.BangGia WHERE maHang = ''KEO'' AND gia = 6000), 1, 0);
SET @info = CONCAT(N''rows: '', (SELECT STRING_AGG(CONCAT(maHang, ''='', gia), '', '') FROM dbo.BangGia));',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. The price list now: BUT unchanged (old date), VO 13000, THUOC 7500, TAY kept, KEO added | Bảng giá giờ: BUT không đổi (ngày cũ), VO 13000, THUOC 7500, TAY còn, KEO thêm'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. The price list now: BUT unchanged (old date), VO 13000, THUOC 7500, TAY kept, KEO added | Bảng giá giờ: BUT không đổi (ngày cũ), VO 13000, THUOC 7500, TAY còn, KEO thêm', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: Running it again changes nothing and reports nothing
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @r TABLE (hanhDong NVARCHAR(10), maHang VARCHAR(10), gia DECIMAL(12,0));
INSERT INTO @r EXEC dbo.prDongBoGia;
SET @ok = IIF((SELECT COUNT(*) FROM @r) = 0 AND (SELECT COUNT(*) FROM dbo.BangGia) = 5, 1, 0);
SET @info = CONCAT(N''second run reported '', (SELECT COUNT(*) FROM @r), N'' rows'');',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Running it again changes nothing and reports nothing | Chạy lại không đổi gì và không báo gì'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. Running it again changes nothing and reports nothing | Chạy lại không đổi gì và không báo gì', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 4: Safe under concurrency: HOLDLOCK on the target
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @d NVARCHAR(MAX) = OBJECT_DEFINITION(OBJECT_ID(N''dbo.prDongBoGia''));
SET @ok = IIF(@d LIKE N''%HOLDLOCK%'' OR @d LIKE N''%SERIALIZABLE%'', 1, 0);
SET @info = N''expected MERGE dbo.BangGia WITH (HOLDLOCK)'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 4. Safe under concurrency: HOLDLOCK on the target | An toàn khi song song: HOLDLOCK trên bảng đích'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 4. Safe under concurrency: HOLDLOCK on the target | An toàn khi song song: HOLDLOCK trên bảng đích', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);

